import{_ as o,l,o as e,c as i,v as t,p as n,x as r,d as A,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"VLAN","description":"","frontmatter":{"title":"VLAN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vlan.md","filePath":"cs/vlan.md","lastUpdated":1789023840000}'),E={name:"cs/vlan.md"};function p(h,a,V,_,m,N){const s=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="vlan" tabindex="-1">VLAN <a class="header-anchor" href="#vlan" aria-label="Permalink to &quot;VLAN&quot;">​</a></h1><div class="epigraph"><p>在同一台交换机上把端口划进不同广播域；帧上的 VLAN 标签让中继口带着多个网段走。</p><footer>—— 据 IEEE 802.1Q；Kurose and Ross 对虚拟局域网的整理</footer></div><p><a href="/cs/csma-ca">上一课</a>对照了无线共享介质。回到交换式以太网：<a href="/cs/csma-switch">CSMA 与交换</a>默认不分割广播域，ARP 与未知单播仍会泛洪到所有端口。缺口是<strong>用标签切广播域</strong>，而不必为每个部门买一台物理交换机。本课不把生成树在 VLAN 上的实例写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播域过大：ARP、DHCP、未知 MAC 泛洪变成全楼噪声，也把不该互访的主机放进同一二层。物理分交换机成本高、线多。VLAN：接入端口属于某个 VID；中继口在帧头加 802.1Q 标签（VID + 优先级）。同一 VID 才二层转发。缺口是广播域的虚拟化，不是 IP 子网公式——子网常与 VLAN 一对一配置，但是后课编址才定义。</p><p><span class="marginnote">Native VLAN 是中继上无标签的那一套；配置不一致会造成泄漏到错误广播域。本课只钉标签切域，不写交换机命令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入端口按 PVID 给未标签帧分类；出中继则插标签。交换转发键变成 (MAC, VID)，而不是裸 MAC。两个 VLAN 要通信必须上升到 IP、经路由器或三层口，即使线插在同一机箱。</p>',8)),(e(),n(c,null,{default:r(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACCESS%5B%22%E6%8E%A5%E5%85%A5%E5%8F%A3%3A%20%E4%B8%80%E4%B8%AA%20VID%22%5D%20--%3E%20SW%5B%22%E6%8C%89%20MAC%20%E4%B8%8E%20VID%20%E8%BD%AC%E5%8F%91%22%5D%0A%20%20TRUNK%5B%22%E4%B8%AD%E7%BB%A7%E5%8F%A3%3A%20%E6%A0%87%E7%AD%BE%E5%A4%8D%E7%94%A8%22%5D%20--%3E%20SW%0A%20%20SW%20--%3E%20ROUTER%5B%22%E8%B7%A8%20VLAN%20%E5%BF%85%E9%A1%BB%E8%B5%B0%E4%B8%89%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VLAN 把「一台交换机 = 一个广播域」拆开，让<a href="/cs/frame-mac">帧与 MAC</a> 的泛洪范围可配。它不提供机密性：标签可被错误配置或被中继口上的主机看到；隔离是管理约定加端口信任，不是密码。端到端论证不变：切域改善的是噪声与误连，不是文件校验。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 VXLAN 等覆盖网作为主干，不把专用 VLAN 与私有 VLAN 的全部端口角色展开。环路问题下一课生成树：VLAN 可以每 VID 一棵树，但先要有树。也不把 VLAN 当防火墙替代——安全课再谈边界。</p><p>后课默认：广播域可以小于一台交换机。冗余链路仍会把泛洪放大成环，下一课生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>802.1Q 用 VID 分割广播域；跨域要三层。</li><li>转发键是 MAC 加 VLAN，不是只学 MAC。</li><li>环路仍在，下一课生成树。</li><li>出处：IEEE 802.1Q；Kurose and Ross。</li></ul>',7))])}const B=o(E,[["render",p]]);export{f as __pageData,B as default};
